450:   private _readStructuralElement(
451:     element: docs_v1.Schema$StructuralElement,
452:   ): string {
453:     let text = '';
454:     if (element.paragraph) {
455:       element.paragraph.elements?.forEach((pElement) => {
456:         if (pElement.textRun && pElement.textRun.content) {
457:           text += pElement.textRun.content;
458:         }
459:       });
460:     } else if (element.table) {
461:       element.table.tableRows?.forEach((row) => {
462:         row.tableCells?.forEach((cell) => {
463:           cell.content?.forEach((cellContent) => {
464:             text += this._readStructuralElement(cellContent);
465:           });
466:         });
467:       });
468:     }
469:     return text;
470:   }
