670:   private _generateReplacementRequests(
671:     content: docs_v1.Schema$StructuralElement[] | undefined,
672:     tabId: string | undefined | null,
673:     findText: string,
674:     processedText: string,
675:     originalFormattingRequests: docs_v1.Schema$Request[],
676:   ): docs_v1.Schema$Request[] {
677:     const requests: docs_v1.Schema$Request[] = [];
678:     const documentText = this._getFullDocumentText(content);
679:     const occurrences: number[] = [];
680:     let searchIndex = 0;
681:     while ((searchIndex = documentText.indexOf(findText, searchIndex)) !== -1) {
682:       occurrences.push(searchIndex + 1);
683:       searchIndex += findText.length;
684:     }
685: 
686:     const lengthDiff = processedText.length - findText.length;
687:     let cumulativeOffset = 0;
688: 
689:     for (let i = 0; i < occurrences.length; i++) {
690:       const occurrence = occurrences[i];
691:       const adjustedPosition = occurrence + cumulativeOffset;
692: 
693:       // Delete old text
694:       requests.push({
695:         deleteContentRange: {
696:           range: {
697:             tabId: tabId,
698:             startIndex: adjustedPosition,
699:             endIndex: adjustedPosition + findText.length,
700:           },
701:         },
702:       });
703: 
704:       // Insert new text
