              fields: 'mimeType',
              supportsAllDrives: true,
            });
            if (file.data.mimeType === 'application/vnd.google-apps.folder') {
              isFolder = true;
            }
          } catch {
            logToFile(
              `Could not determine type of ID from URL, treating as file: ${fileId}`,
            );
