499: 
500:       // If threadId is provided, fetch the last message to get reply headers
501:       let inReplyTo: string | undefined;
502:       let references: string | undefined;
503:       if (threadId) {
504:         try {
505:           const threadResponse = await gmail.users.threads.get({
506:             userId: 'me',
507:             id: threadId,
508:             format: 'metadata',
509:             metadataHeaders: ['Message-ID', 'References'],
510:           });
511:           const messages = threadResponse.data.messages || [];
512:           if (messages.length > 0) {
513:             const lastMessage = messages[messages.length - 1];
514:             const headers = lastMessage.payload?.headers || [];
515:             const messageIdHeader = headers.find(
516:               (h) => h.name?.toLowerCase() === 'message-id',
517:             );
518:             const referencesHeader = headers.find(
519:               (h) => h.name?.toLowerCase() === 'references',
520:             );
521:             if (messageIdHeader?.value) {
522:               inReplyTo = messageIdHeader.value;
523:               const previousReferences = referencesHeader?.value || '';
524:               references = previousReferences
525:                 ? `${previousReferences} ${messageIdHeader.value}`
526:                 : messageIdHeader.value;
527:             }
528:           }
529:         } catch (threadError) {
530:           logToFile(
531:             `Warning: Could not fetch thread ${threadId} for reply headers: ${threadError}`,
532:           );
533:         }
534:       }
535: 
536:       // Create MIME message
537:       const mimeMessage = MimeHelper.createMimeMessage({
538:         to: Array.isArray(to) ? to.join(', ') : to,
539:         subject,
540:         body,
541:         cc: cc ? (Array.isArray(cc) ? cc.join(', ') : cc) : undefined,
542:         bcc: bcc ? (Array.isArray(bcc) ? bcc.join(', ') : bcc) : undefined,
543:         isHtml,
544:         inReplyTo,
545:         references,
546:       });
